    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    if (andes) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.andes.field = read_register_64(bus_, regno_csr(addr));
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          state.andes.pmacfg[i] =
            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          state.andes.pmaaddr[i] =
            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
    }
    if (mext) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
      HYBRID_M_EXT_CSR_LIST(X)
#undef X
    }
  }

  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
  // L26: guards on the configured scratch GPA so a V drain never stores to a
  // bogus address (mirror of ResumeDriver's reload-sweep guard).
  void dump_v_to_scratch(uint64_t vlenb)
  {
    if (scratch_gpa_ == kVScratchGpaUnset)
      throw std::runtime_error(
        "StateDrain: V state present but scratch GPA unset");
    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);

1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <cstdint>
15	
16	namespace hybrid
17	{
18	
19	class StateDrain
20	{
21	public:
22	  using RD = ResumeDriver;
23	
24	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
25	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
26	  // unset sentinel; only the V dump sweep consults it, and it throws there if
27	  // a V drain is reached with the GPA unset (no silent dump to a bogus
28	  // address). The simulator passes the real value from platform.main_memory.
29	  // caps: which Andes custom CSRs the TARGET core implements (from its
30	  // config.inc, supplied by the sim binary). Defaults to all() so existing
31	  // call sites are unchanged. Gates the Andes re-read below: reading an
32	  // unimplemented CSR can stall the DM, same as restoring one.
33	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
34	                      AndesCaps caps = AndesCaps::all())
35	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
36	  {}
37	
38	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
39	  // drain_with_passthrough when the QEMU 1 snapshot is available.
40	  auto drain() -> hybrid_state_v1
41	  {
42	    hybrid_state_v1 state{};
43	    state.magic   = HYBRID_STATE_MAGIC;
44	    state.version = HYBRID_STATE_VERSION;
45	    state.flags   = HYBRID_FLAG_RV64;
46	    halt_and_capture_pc_priv(state);
47	
48	    for (uint16_t i = 1; i < 32; ++i)
49	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
50	
51	    return state;
52	  }
53	
54	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
55	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
56	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
57	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
58	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
59	  // and vreg remain pass-through (read-only / too large for DM).
60	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
61	  // contribution would otherwise be discarded as the passthrough preserves
62	  // QEMU1's pre-handoff value.
63	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
64	  {
65	    auto state = input;
66	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
67	
68	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
69	    // like the resume side -- the Program Buffer is reserved for state the
70	    // abstract command space cannot reach (the V regfile, vtype/vl).
71	    for (uint16_t i = 1; i < 32; ++i)
72	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
73	
74	    if (input.flags & HYBRID_FLAG_FP) {
75	      for (uint16_t i = 0; i < 32; ++i)
76	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
77	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
78	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
79	    }
80	
81	    if (input.flags & HYBRID_FLAG_V) {
82	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
83	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
84	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
85	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
86	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
87	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
88	    }
89	
90	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
91	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
92	    // dropped and the stale QEMU1 value passes through into the drained state.
93	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
94	
95	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
96	    // restores them), so re-read them -- an in-ROI write must reach the drained
97	    // state instead of the stale QEMU1 passthrough value.
98	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
99	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
100	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
101	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
102	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
103	
104	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
105	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
106	
107	    // Andes V5 CSR block (v3): re-read the transported Andes CSRs from the hart
108	    // so an in-ROI write reaches the drained state instead of the stale QEMU1
109	    // passthrough (same round-trip as mscratch). caps_ gates each read to the
110	    // CSRs the core implements (reading an absent custom CSR can stall the DM,
111	    // same as restoring one); a skipped CSR keeps its passthrough value.
112	    // HYBRID_ANDES_CSR_LIST is the single source of truth shared with the
113	    // plugin drain, ResumeDriver, and state_diff.
114	    if (input.flags & HYBRID_FLAG_ANDES) {
115	#define X(field, addr, name) \
116	  if (caps_.supports_csr(addr)) \
117	    state.andes.field = read_register_64(bus_, regno_csr(addr));
118	      HYBRID_ANDES_CSR_LIST(X)
119	#undef X
120	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
121	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
122	          state.andes.pmacfg[i] =
123	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
124	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
125	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
126	          state.andes.pmaaddr[i] =
127	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
128	    }
129	
130	    // V data regfile: dump v0..v31 to the shared scratch region via the
131	    // Program Buffer LAST -- after every architectural read above -- so the
132	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
133	    // cannot corrupt the values already captured. The simulator's
134	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
135	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
136	    if (input.flags & HYBRID_FLAG_V)
137	      dump_v_to_scratch(input.vlenb);
138	
139	    return state;
140	  }
141	
142	private:
143	  // Halt the hart and capture the two control fields every drain path needs:
144	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
145	  // blocks are filled by the caller, so drain() and drain_with_passthrough
146	  // share one halt + prologue. dmactive must transition 0->1 in its own write
147	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
148	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
149	  {
150	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
151	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
152	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
153	                   "StateDrain halt");
154	
155	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
156	                                  "StateDrain DCSR") & 0x3u;
157	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
158	  }
159	
160	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
161	  // L26: guards on the configured scratch GPA so a V drain never stores to a
162	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
163	  void dump_v_to_scratch(uint64_t vlenb)
164	  {
165	    if (scratch_gpa_ == kVScratchGpaUnset)
166	      throw std::runtime_error(
167	        "StateDrain: V state present but scratch GPA unset");
168	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
169	  }
170	
171	  DmiBus& bus_;
172	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
173	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
174	};
