298	
299	  void write_64bit_register(uint16_t regno, uint64_t value)
300	  {
301	    write_register_abstract(bus_, regno, value);
302	  }
303	
304	  // Abstract-first CSR write with Program Buffer fallback.
305	  // Tries an abstract register write; if the DM signals cmderr, clears it,
306	  // stages the value in scratch_gpr via abstract GPR write, then executes a
307	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
308	  // to x5 (t0) which the GPR restore loop overwrites later.
309	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
310	                                 uint8_t scratch_gpr = 5)
311	  {
312	    write_64bit_register(regno_csr(csr), value);
313	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
314	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
315	    write_64bit_register(regno_gpr(scratch_gpr), value);
316	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
317	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
318	  }
319	
320	  // Write a CSR-addressable register and clear any cmderr the DM raised.
321	  // Used for CSRs whose abstract-access support may be implementation
322	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
323	  // remaining writes.
324	  void write_csr_tolerant(uint16_t csr, uint64_t value)
325	  {
326	    write_64bit_register(regno_csr(csr), value);
327	    clear_cmderr_if_set();
328	  }
329	
330	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
331	  // is rejected until the bits are W1C-cleared. We tolerate per-register
332	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
333	  // error before resuming so the hart isn't left in a stuck state.
334	  // B17: record the last observed non-zero cmderr and a clear count so a
335	  // partially-broken restore is observable via the public accessors
336	  // instead of silently swallowed.
337	  void clear_cmderr_if_set()
338	  {
339	    const auto status = bus_.read(kAbstractcs);
340	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
341	    if (code != 0u) {
342	      last_observed_cmderr_ = code;
343	      ++cmderr_clear_count_;
344	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
345	    }
346	  }
347	
348	  DmiBus& bus_;
349	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
350	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
351	  uint32_t last_observed_cmderr_ = 0;
352	  uint64_t cmderr_clear_count_   = 0;
353	
354	public:
355	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
356	  // at least one abstract write tripped a sticky cmderr the restore
357	  // tolerated by clearing. cmderr_clear_count() is the total number of
358	  // such clears across all calls into clear_cmderr_if_set() this run.
359	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
360	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
361	};
362	
363	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
364	// via an Abstract Command. Halts-and-reads contract: caller must have the
365	// hart in the halted state. Shared by StateDrain (drain at exit). If
366	// abstractcs.cmderr goes sticky after the command, the helper clears it and
367	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
368	// instead of corrupting the adjacent field.
369	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
370	                                     const char* poll_label
371	                                       = "read_register_64")
372	  -> std::optional<uint64_t>
373	{
374	  using RD = ResumeDriver;
375	  bus.write(RD::kCommand,
376	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
377	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
378	  const auto status = bus.read(RD::kAbstractcs);
379	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
380	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
381	    return std::nullopt;
382	  }
383	  const uint64_t lo = bus.read(RD::kData0);
384	  const uint64_t hi = bus.read(RD::kData1);
385	  return lo | (hi << 32);
386	}
387	
388	inline auto read_register_64(DmiBus& bus, uint16_t regno,
389	                             const char* poll_label = "read_register_64")
390	  -> uint64_t
391	{
392	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
393	}
